final class ProofDetailViewController: UIViewController {
    private let record: ProofRecord; private let environment: AppEnvironment; private let stack = UIStackView()
    init(record: ProofRecord, environment: AppEnvironment) { self.record = record; self.environment = environment; super.init(nibName: nil, bundle: nil) }; required init?(coder: NSCoder) { fatalError() }
    override func viewDidLoad() { super.viewDidLoad(); title = "Proof Detail"; view.backgroundColor = AppColors.background; buildUI() }
    private func buildUI() { let scroll = UIScrollView(); scroll.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(scroll); stack.axis = .vertical; stack.spacing = AppSpacing.md; stack.translatesAutoresizingMaskIntoConstraints = false; scroll.addSubview(stack); NSLayoutConstraint.activate([scroll.topAnchor.constraint(equalTo: view.topAnchor), scroll.bottomAnchor.constraint(equalTo: view.bottomAnchor), scroll.leadingAnchor.constraint(equalTo: view.leadingAnchor), scroll.trailingAnchor.constraint(equalTo: view.trailingAnchor), stack.topAnchor.constraint(equalTo: scroll.contentLayoutGuide.topAnchor, constant: AppSpacing.md), stack.leadingAnchor.constraint(equalTo: scroll.frameLayoutGuide.leadingAnchor, constant: AppSpacing.md), stack.trailingAnchor.constraint(equalTo: scroll.frameLayoutGuide.trailingAnchor, constant: -AppSpacing.md), stack.bottomAnchor.constraint(equalTo: scroll.contentLayoutGuide.bottomAnchor, constant: -AppSpacing.lg)]); let player = AVPlayerViewController(); player.player = AVPlayer(url: record.localAssetURL); player.view.heightAnchor.constraint(equalToConstant: 230).isActive = true; addChild(player); stack.addArrangedSubview(player.view); player.didMove(toParent: self); let heading = UIBuilder.label(record.protectionStatus.title, style: AppTypography.title, color: record.protectionStatus == .protected ? AppColors.success : AppColors.warning); stack.addArrangedSubview(heading); let summary = UIBuilder.label("\(record.protectionStatus == .protected ? "✓ File integrity" : "○ File integrity incomplete")\n\(record.provenanceStatus == .verifiedOriginal ? "✓ Content Credentials" : "○ Content Credentials unavailable")\n\(record.publicKeyFingerprint == nil ? "○ Hardware evidence unavailable" : "✓ Hardware evidence recorded")\n○ Network timestamp unavailable in Phase 1", style: AppTypography.body); stack.addArrangedSubview(summary); let actions = [UIBuilder.button("Share Protected Original", image: UIImage(systemName: "square.and.arrow.up")), UIBuilder.button("View Technical Proof", image: UIImage(systemName: "doc.text.magnifyingglass"), primary: false), UIBuilder.button("Compare With Another File", image: UIImage(systemName: "arrow.triangle.2.circlepath"), primary: false), UIBuilder.button("Delete Original", image: UIImage(systemName: "trash"), primary: false)]; actions[0].addTarget(self, action: #selector(share), for: .touchUpInside); actions[1].addTarget(self, action: #selector(technical), for: .touchUpInside); actions[2].addTarget(self, action: #selector(compare), for: .touchUpInside); actions[3].addTarget(self, action: #selector(deleteOriginal), for: .touchUpInside); actions.forEach { stack.addArrangedSubview($0) }; addMetadata("CAPTURE", ["Date     \(record.createdAt.formatted(date: .abbreviated, time: .omitted))", "Time     \(record.createdAt.formatted(date: .omitted, time: .shortened))", "Duration     \(record.duration > 0 ? String(format: "%.0fs", record.duration) : "Not available")", "Resolution     \(record.width > 0 ? "\(record.width) × \(record.height)" : "Not available")", "Frame rate     \(record.frameRate > 0 ? "\(record.frameRate, specifier: "%.1f") FPS" : "Not available")"]); addMetadata("LOCATION", [record.locationDisclosure.title]); }
    private func addMetadata(_ title: String, _ rows: [String]) { stack.addArrangedSubview(UIBuilder.label(title, style: AppTypography.caption, color: AppColors.secondaryText)); rows.forEach { let l = UIBuilder.label($0, style: AppTypography.body); l.backgroundColor = AppColors.surface; l.layer.cornerRadius = AppRadius.button; l.layer.masksToBounds = true; stack.addArrangedSubview(l); l.heightAnchor.constraint(greaterThanOrEqualToConstant: 44).isActive = true } }
    @objc private func share() { guard FileManager.default.fileExists(atPath: record.localAssetURL.path) else { return }; present(UIActivityViewController(activityItems: [record.localAssetURL], applicationActivities: nil), animated: true) }
    @objc private func technical() { navigationController?.pushViewController(TechnicalProofViewController(record: record, environment: environment), animated: true) }
    @objc private func compare() { navigationController?.pushViewController(CompareViewController(original: record.localAssetURL, environment: environment), animated: true) }
    @objc private func deleteOriginal() { let alert = UIAlertController(title: "Delete Protected Original?", message: "TrueCut does not keep a server copy of this video. If this is your only copy, deleting it may permanently remove the media needed for future verification.", preferredStyle: .alert); alert.addAction(UIAlertAction(title: "Cancel", style: .cancel)); alert.addAction(UIAlertAction(title: "Delete Original", style: .destructive) { [weak self] _ in self?.authenticateAndDelete() }); present(alert, animated: true) }
    private func authenticateAndDelete() { let context = LAContext(); context.evaluatePolicy(.deviceOwnerAuthentication, localizedReason: "Authenticate before deleting this local original.") { [weak self] success, _ in guard success, let self else { return }; try? FileManager.default.removeItem(at: self.record.localAssetURL); Task { try? await self.environment.proofRepository.delete(self.record); await MainActor.run { self.navigationController?.popViewController(animated: true) } } } }
}

final class TechnicalProofViewController: UIViewController {
    private let record: ProofRecord; private let environment: AppEnvironment
    init(record: ProofRecord, environment: AppEnvironment) { self.record = record; self.environment = environment; super.init(nibName: nil, bundle: nil) }; required init?(coder: NSCoder) { fatalError() }
    override func viewDidLoad() { super.viewDidLoad(); title = "Technical Proof"; view.backgroundColor = AppColors.background; let text = UIBuilder.label("CAPTURE ID\n\(record.captureId)\n\nLOCAL DIGEST\n\(record.digestHex ?? "Not available")\n\nDIGEST ALGORITHM\nSHA-256\n\nPUBLIC KEY FINGERPRINT\n\(record.publicKeyFingerprint ?? "Not available")\n\nSIGNATURE STATUS\n\(record.publicKeyFingerprint == nil ? "Not available" : "Evidence recorded locally")\n\nC2PA MANIFEST STATUS\n\(record.provenanceStatus == .verifiedOriginal ? "Validated locally" : "Not available")\n\nASSET BINDING\n\(record.provenanceStatus == .verifiedOriginal ? "Valid" : "Not available")\n\nLOCATION DISCLOSURE\n\(record.locationDisclosure.title)", style: AppTypography.mono); text.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(text); NSLayoutConstraint.activate([text.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: AppSpacing.md), text.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: AppSpacing.md), text.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -AppSpacing.md)]) }
}

final class CompareViewController: UIViewController, UIDocumentPickerDelegate {
    private let original: URL; private let environment: AppEnvironment; private let result = UIBuilder.label("Select another MP4 or MOV to compare locally.", style: AppTypography.body); init(original: URL, environment: AppEnvironment) { self.original = original; self.environment = environment; super.init(nibName: nil, bundle: nil) }; required init?(coder: NSCoder) { fatalError() }
    override func viewDidLoad() { super.viewDidLoad(); title = "Compare"; view.backgroundColor = AppColors.background; let choose = UIBuilder.button("Choose Candidate Video", image: AppIcons.folder); choose.addTarget(self, action: #selector(pick), for: .touchUpInside); result.translatesAutoresizingMaskIntoConstraints = false; choose.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(result); view.addSubview(choose); NSLayoutConstraint.activate([result.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: AppSpacing.lg), result.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: AppSpacing.md), result.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -AppSpacing.md), choose.topAnchor.constraint(equalTo: result.bottomAnchor, constant: AppSpacing.md), choose.centerXAnchor.constraint(equalTo: view.centerXAnchor)]) }
    @objc private func pick() { let picker = UIDocumentPickerViewController(forOpeningContentTypes: [UTType.movie]); picker.delegate = self; present(picker, animated: true) }
    func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) { guard let candidate = urls.first else { return }; result.text = "Comparing locally…"; AppLogger.step("Compare: digesting original and candidate"); Task { let comparison = try? await environment.comparisonService.compare(original: original, candidate: candidate); await MainActor.run { self.result.text = comparison?.identical == true ? "FILES IDENTICAL\n\nThe candidate matches the protected original digest." : "FILES DIFFER\n\nThe selected file is not identical to this protected TrueCut original.\n\nThis does not by itself establish that either file is fabricated or AI-generated." } } }
}

final class InspectorViewController: UIViewController, UIDocumentPickerDelegate {
    private let environment: AppEnvironment; private let result = UIBuilder.label("Inspect a Video\n\nCheck supported provenance and integrity information for a video you've received.", style: AppTypography.title); init(environment: AppEnvironment) { self.environment = environment; super.init(nibName: nil, bundle: nil) }; required init?(coder: NSCoder) { fatalError() }
    override func viewDidLoad() { super.viewDidLoad(); title = "Inspect"; view.backgroundColor = AppColors.background; result.textAlignment = .center; let choose = UIBuilder.button("Choose Video", image: AppIcons.folder); choose.addTarget(self, action: #selector(pick), for: .touchUpInside); result.translatesAutoresizingMaskIntoConstraints = false; choose.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(result); view.addSubview(choose); NSLayoutConstraint.activate([result.centerXAnchor.constraint(equalTo: view.centerXAnchor), result.centerYAnchor.constraint(equalTo: view.centerYAnchor, constant: -40), result.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: AppSpacing.lg), result.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -AppSpacing.lg), choose.topAnchor.constraint(equalTo: result.bottomAnchor, constant: AppSpacing.lg), choose.centerXAnchor.constraint(equalTo: view.centerXAnchor)]) }
    @objc private func pick() { let picker = UIDocumentPickerViewController(forOpeningContentTypes: [UTType.movie]); picker.delegate = self; present(picker, animated: true) }
    func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) { guard let url = urls.first else { return }; result.text = "ANALYZING\n\nReading file\nChecking Content Credentials\nValidating provenance"; AppLogger.step("Inspect: starting local C2PA verification"); Task { let provenance = try? await environment.credentialsService.verify(assetURL: url); await MainActor.run { self.result.text = provenance?.message ?? "Unable to inspect this file."; self.result.font = AppTypography.body } } }
}

final class SettingsViewController: UIViewController {
    private let environment: AppEnvironment; init(environment: AppEnvironment) { self.environment = environment; super.init(nibName: nil, bundle: nil) }; required init?(coder: NSCoder) { fatalError() }
    override func viewDidLoad() { super.viewDidLoad(); title = "Settings"; view.backgroundColor = AppColors.background; let scroll = UIScrollView(); let stack = UIStackView(); stack.axis = .vertical; stack.spacing = AppSpacing.sm; stack.translatesAutoresizingMaskIntoConstraints = false; scroll.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(scroll); scroll.addSubview(stack); NSLayoutConstraint.activate([scroll.topAnchor.constraint(equalTo: view.topAnchor), scroll.bottomAnchor.constraint(equalTo: view.bottomAnchor), scroll.leadingAnchor.constraint(equalTo: view.leadingAnchor), scroll.trailingAnchor.constraint(equalTo: view.trailingAnchor), stack.topAnchor.constraint(equalTo: scroll.contentLayoutGuide.topAnchor, constant: AppSpacing.md), stack.leadingAnchor.constraint(equalTo: scroll.frameLayoutGuide.leadingAnchor, constant: AppSpacing.md), stack.trailingAnchor.constraint(equalTo: scroll.frameLayoutGuide.trailingAnchor, constant: -AppSpacing.md), stack.bottomAnchor.constraint(equalTo: scroll.contentLayoutGuide.bottomAnchor, constant: -AppSpacing.lg)]); stack.addArrangedSubview(UIBuilder.label("TrueCut Settings", style: AppTypography.title)); addSection("CAMERA", ["Resolution     High", "Frame Rate     Auto", "Grid           Off", "Audio Recording     On"], to: stack); addSection("PRIVACY", ["Location disclosure"], to: stack); let location = UISegmentedControl(items: LocationDisclosure.allCases.map(\.title)); location.selectedSegmentIndex = 0; stack.addArrangedSubview(location); addSection("PROTECTION", ["Hardware Protection Status     Device-reported", "Content Credentials Status     Local C2PA", "Public Key Fingerprint     Created locally during capture"], to: stack); let face = UISwitch(); face.isOn = UserDefaults.standard.bool(forKey: "requireFaceID"); face.addTarget(self, action: #selector(faceIDChanged(_:)), for: .valueChanged); let faceRow = UIStackView(arrangedSubviews: [UIBuilder.label("Require Face ID for Proof Vault"), face]); faceRow.alignment = .center; faceRow.distribution = .equalSpacing; stack.addArrangedSubview(faceRow); addSection("STORAGE", ["Original videos remain on this device.", "TrueCut does not upload your original videos in this version."], to: stack); addSection("ABOUT", ["How TrueCut Works", "Privacy", "Terms", "App Version 1.0"], to: stack) }
    @objc private func faceIDChanged(_ sender: UISwitch) { UserDefaults.standard.set(sender.isOn, forKey: "requireFaceID") }
    private func addSection(_ title: String, _ rows: [String], to stack: UIStackView) { stack.addArrangedSubview(UIBuilder.label(title, style: AppTypography.caption, color: AppColors.secondaryText)); rows.forEach { let l = UIBuilder.label($0, style: AppTypography.body); l.backgroundColor = AppColors.surface; l.layer.cornerRadius = AppRadius.button; l.layer.masksToBounds = true; l.isAccessibilityElement = true; l.accessibilityLabel = $0; stack.addArrangedSubview(l); l.heightAnchor.constraint(greaterThanOrEqualToConstant: 48).isActive = true } }
}
